                var ret = new Key.Mask<R>();
                this.Translate_InternalFill(ret, eval);
                return ret;
            }

            protected void Translate_InternalFill<R>(Mask<R> obj, Func<TItem, R> eval)
            {
                base.Translate_InternalFill(obj, eval);
                obj.EDID = eval(this.EDID);
                obj.ObjectBounds = this.ObjectBounds == null ? null : new MaskItem<R, ObjectBounds.Mask<R>?>(eval(this.ObjectBounds.Overall), this.ObjectBounds.Specific?.Translate(eval));
                obj.PreviewTransform = eval(this.PreviewTransform);
                obj.XALG = eval(this.XALG);
                if (ObjectPlacementDefaults != null)
                {
                    obj.ObjectPlacementDefaults = new MaskItem<R, IEnumerable<MaskItemIndexed<R, ObjectPlacementDefault.Mask<R>?>>?>(eval(this.ObjectPlacementDefaults.Overall), []);
                    if (ObjectPlacementDefaults.Specific != null)
                    {
                        var l = new List<MaskItemIndexed<R, ObjectPlacementDefault.Mask<R>?>>();
                        obj.ObjectPlacementDefaults.Specific = l;
                        foreach (var item in ObjectPlacementDefaults.Specific)
                        {
                            MaskItemIndexed<R, ObjectPlacementDefault.Mask<R>?>? mask = item == null ? null : new MaskItemIndexed<R, ObjectPlacementDefault.Mask<R>?>(item.Index, eval(item.Overall), item.Specific?.Translate(eval));
                            if (mask == null) continue;
                            l.Add(mask);
                        }
                    }
                }
                obj.FULL = eval(this.FULL);
                obj.Model = this.Model == null ? null : new MaskItem<R, Model.Mask<R>?>(eval(this.Model.Overall), this.Model.Specific?.Translate(eval));
                obj.ENLM = eval(this.ENLM);
                obj.ENLT = eval(this.ENLT);
                obj.ENLS = eval(this.ENLS);
                obj.AUUV = eval(this.AUUV);
                obj.ICON = eval(this.ICON);
                obj.MICO = eval(this.MICO);
                obj.Destructible = this.Destructible == null ? null : new MaskItem<R, Destructible.Mask<R>?>(eval(this.Destructible.Overall), this.Destructible.Specific?.Translate(eval));
                obj.PickUpSound = eval(this.PickUpSound);
                obj.PutDownSound = eval(this.PutDownSound);
                if (Keywords != null)
                {
                    obj.Keywords = new MaskItem<R, IEnumerable<(int Index, R Value)>?>(eval(this.Keywords.Overall), []);
                    if (Keywords.Specific != null)
                    {
                        var l = new List<(int Index, R Item)>();
                        obj.Keywords.Specific = l;
                        foreach (var item in Keywords.Specific)
                        {
                            R mask = eval(item.Value);
                            l.Add((item.Index, mask));
                        }
                    }
                }
                obj.ValueCurrency = eval(this.ValueCurrency);
                obj.DESC = eval(this.DESC);
                obj.AQIC = eval(this.AQIC);
                obj.Quest = eval(this.Quest);
                obj.Data = this.Data == null ? null : new MaskItem<R, ValueWeight.Mask<R>?>(eval(this.Data.Overall), this.Data.Specific?.Translate(eval));
                obj.VMAD = eval(this.VMAD);
            }
