            }
            if ((equalsMask?.GetShouldTranslate((int)Key_FieldIndex.FULL) ?? true))
            {
                if (!object.Equals(lhs.FULL, rhs.FULL)) return false;
            }
            if ((equalsMask?.GetShouldTranslate((int)Key_FieldIndex.Model) ?? true))
