            {
                if (!lhs.ENLS.EqualsWithin(rhs.ENLS)) return false;
            }
            if ((equalsMask?.GetShouldTranslate((int)Key_FieldIndex.AUUV) ?? true))
            {
                if (!MemorySliceExt.SequenceEqual(lhs.AUUV, rhs.AUUV)) return false;
            }
            if ((equalsMask?.GetShouldTranslate((int)Key_FieldIndex.ICON) ?? true))
            {
                if (!string.Equals(lhs.ICON, rhs.ICON)) return false;
            }
            if ((equalsMask?.GetShouldTranslate((int)Key_FieldIndex.MICO) ?? true))
            {
                if (!string.Equals(lhs.MICO, rhs.MICO)) return false;
            }
            if ((equalsMask?.GetShouldTranslate((int)Key_FieldIndex.Destructible) ?? true))
            {
                if (EqualsMaskHelper.RefEquality(lhs.Destructible, rhs.Destructible, out var lhsDestructible, out var rhsDestructible, out var isDestructibleEqual))
                {
                    if (!((DestructibleCommon)((IDestructibleGetter)lhsDestructible).CommonInstance()!).Equals(lhsDestructible, rhsDestructible, equalsMask?.GetSubCrystal((int)Key_FieldIndex.Destructible))) return false;
