            if ((equalsMask?.GetShouldTranslate((int)Key_FieldIndex.PutDownSound) ?? true))
            {
                if (!lhs.PutDownSound.Equals(rhs.PutDownSound)) return false;
            }
            if ((equalsMask?.GetShouldTranslate((int)Key_FieldIndex.Keywords) ?? true))
            {
                if (!lhs.Keywords.SequenceEqualNullable(rhs.Keywords)) return false;
            }
            if ((equalsMask?.GetShouldTranslate((int)Key_FieldIndex.ValueCurrency) ?? true))
            {
                if (!lhs.ValueCurrency.Equals(rhs.ValueCurrency)) return false;
            }
            if ((equalsMask?.GetShouldTranslate((int)Key_FieldIndex.DESC) ?? true))
            {
                if (!object.Equals(lhs.DESC, rhs.DESC)) return false;
            }
            if ((equalsMask?.GetShouldTranslate((int)Key_FieldIndex.AQIC) ?? true))
            {
                if (!MemorySliceExt.SequenceEqual(lhs.AQIC, rhs.AQIC)) return false;
            }
            if ((equalsMask?.GetShouldTranslate((int)Key_FieldIndex.Quest) ?? true))
            {
