                package: package)
        {
            this.CustomCtor();
        }

        public static IKeyGetter KeyFactory(
            OverlayStream stream,
            BinaryOverlayFactoryPackage package,
            TypedParseParams translationParams = default)
        {
            stream = Decompression.DecompressStream(stream);
            stream = ExtractRecordMemory(
                stream: stream,
                meta: package.MetaData.Constants,
                memoryPair: out var memoryPair,
                offset: out var offset,
                finalPos: out var finalPos);
            var ret = new KeyBinaryOverlay(
                memoryPair: memoryPair,
                package: package);
            ret._package.FormVersion = ret;
            ret.CustomFactoryEnd(
                stream: stream,
                finalPos: finalPos,
                offset: offset);
            ret.FillSubrecordTypes(
                majorReference: ret,
                stream: stream,
                finalPos: finalPos,
                offset: offset,
                translationParams: translationParams,
                fill: ret.FillRecordType);
            return ret;
        }

        public static IKeyGetter KeyFactory(
            ReadOnlyMemorySlice<byte> slice,
            BinaryOverlayFactoryPackage package,
            TypedParseParams translationParams = default)
        {
            return KeyFactory(
                stream: new OverlayStream(slice, package),
                package: package,
                translationParams: translationParams);
        }

        public override ParseResult FillRecordType(
            OverlayStream stream,
            int finalPos,
            int offset,
            RecordType type,
            PreviousParse lastParsed,
            Dictionary<RecordType, int>? recordParseCount,
            TypedParseParams translationParams = default)
        {
            type = translationParams.ConvertToStandard(type);
            switch (type.TypeInt)
            {
                case RecordTypeInts.EDID:
                {
                    if (!lastParsed.ParsedIndex.HasValue)
                    {
                        return base.FillRecordType(
                            stream: stream,
                            finalPos: finalPos,
                            offset: offset,
                            type: type,
                            lastParsed: lastParsed,
                            recordParseCount: recordParseCount,
                            translationParams: translationParams.WithNoConverter());
                    }
                    else if (lastParsed.ParsedIndex.Value <= (int)MajorRecord_FieldIndex.EditorID)
                    {
                        _EDIDLocation = (stream.Position - offset);
                        return new ParseResult((int)Key_FieldIndex.EDID, type);
                    }
                    else
                    {
                        switch (recordParseCount?.GetOrAdd(type) ?? 0)
                        {
                            case 0:
                            {
                                return base.FillRecordType(
                                    stream: stream,
                                    finalPos: finalPos,
                                    offset: offset,
                                    type: type,
                                    lastParsed: lastParsed,
                                    recordParseCount: recordParseCount,
                                    translationParams: translationParams.WithNoConverter());
                            }
                            case 1:
                            {
                                _EDIDLocation = (stream.Position - offset);
                                return new ParseResult((int)Key_FieldIndex.EDID, type);
                            }
                            default:
                                throw new NotImplementedException();
                        }
                    }
                }
                case RecordTypeInts.OBND:
                {
                    _ObjectBoundsLocation = new RangeInt32((stream.Position - offset), finalPos - offset);
                    return (int)Key_FieldIndex.ObjectBounds;
                }
                case RecordTypeInts.PTRN:
                {
                    _PreviewTransformLocation = (stream.Position - offset);
                    return (int)Key_FieldIndex.PreviewTransform;
                }
                case RecordTypeInts.XALG:
                {
                    _XALGLocation = (stream.Position - offset);
                    return (int)Key_FieldIndex.XALG;
                }
                case RecordTypeInts.OPDS:
                {
                    this.ObjectPlacementDefaults = BinaryOverlayList.FactoryByArray<IObjectPlacementDefaultGetter>(
                        mem: stream.RemainingMemory,
                        package: _package,
                        translationParams: translationParams,
                        getter: (s, p, recConv) => ObjectPlacementDefaultBinaryOverlay.ObjectPlacementDefaultFactory(new OverlayStream(s, p), p, recConv),
                        locs: ParseRecordLocations(
                            stream: stream,
                            trigger: ObjectPlacementDefault_Registration.TriggerSpecs,
                            triggersAlwaysAreNewRecords: true,
                            constants: _package.MetaData.Constants.SubConstants,
                            skipHeader: false));
                    return (int)Key_FieldIndex.ObjectPlacementDefaults;
                }
                case RecordTypeInts.FULL:
                {
                    _FULLLocation = (stream.Position - offset);
                    return (int)Key_FieldIndex.FULL;
                }
                case RecordTypeInts.MODL:
                case RecordTypeInts.MODC:
                case RecordTypeInts.MODT:
                case RecordTypeInts.MODS:
                {
                    this.Model = ModelBinaryOverlay.ModelFactory(
                        stream: stream,
                        package: _package,
                        translationParams: translationParams.DoNotShortCircuit());
                    return (int)Key_FieldIndex.Model;
                }
                case RecordTypeInts.ENLM:
                {
                    _ENLMLocation = (stream.Position - offset);
                    return (int)Key_FieldIndex.ENLM;
                }
                case RecordTypeInts.ENLT:
                {
                    _ENLTLocation = (stream.Position - offset);
                    return (int)Key_FieldIndex.ENLT;
                }
                case RecordTypeInts.ENLS:
                {
                    _ENLSLocation = (stream.Position - offset);
                    return (int)Key_FieldIndex.ENLS;
                }
                case RecordTypeInts.AUUV:
                {
                    _AUUVLocation = (stream.Position - offset);
                    return (int)Key_FieldIndex.AUUV;
                }
                case RecordTypeInts.ICON:
                {
                    _ICONLocation = (stream.Position - offset);
                    return (int)Key_FieldIndex.ICON;
                }
                case RecordTypeInts.MICO:
                {
                    _MICOLocation = (stream.Position - offset);
                    return (int)Key_FieldIndex.MICO;
                }
                case RecordTypeInts.DEST:
                case RecordTypeInts.DAMC:
                case RecordTypeInts.DSTD:
                {
                    this.Destructible = DestructibleBinaryOverlay.DestructibleFactory(
                        stream: stream,
                        package: _package,
                        translationParams: translationParams.DoNotShortCircuit());
                    return (int)Key_FieldIndex.Destructible;
                }
                case RecordTypeInts.YNAM:
                {
                    _PickUpSoundLocation = (stream.Position - offset);
                    return (int)Key_FieldIndex.PickUpSound;
                }
                case RecordTypeInts.ZNAM:
                {
                    _PutDownSoundLocation = (stream.Position - offset);
                    return (int)Key_FieldIndex.PutDownSound;
                }
                case RecordTypeInts.KSIZ:
                case RecordTypeInts.KWDA:
                {
                    this.Keywords = BinaryOverlayList.FactoryByCount<IFormLinkGetter<IKeywordGetter>>(
                        stream: stream,
                        package: _package,
                        itemLength: 0x4,
                        countLength: 4,
                        countType: RecordTypes.KSIZ,
                        trigger: RecordTypes.KWDA,
                        getter: (s, p) => FormLinkBinaryTranslation.Instance.OverlayFactory<IKeywordGetter>(p, s));
                    return (int)Key_FieldIndex.Keywords;
                }
                case RecordTypeInts.VCRY:
                {
                    _ValueCurrencyLocation = (stream.Position - offset);
                    return (int)Key_FieldIndex.ValueCurrency;
                }
                case RecordTypeInts.DESC:
                {
                    _DESCLocation = (stream.Position - offset);
                    return (int)Key_FieldIndex.DESC;
                }
                case RecordTypeInts.AQIC:
                {
                    _AQICLocation = (stream.Position - offset);
                    return (int)Key_FieldIndex.AQIC;
                }
                case RecordTypeInts.DIQO:
                {
                    _QuestLocation = (stream.Position - offset);
                    return (int)Key_FieldIndex.Quest;
                }
                case RecordTypeInts.DATA:
                {
                    _DataLocation = new RangeInt32((stream.Position - offset), finalPos - offset);
                    return (int)Key_FieldIndex.Data;
                }
                case RecordTypeInts.VMAD:
                {
                    _VMADLocation = (stream.Position - offset);
                    return (int)Key_FieldIndex.VMAD;
                }
                default:
                    return base.FillRecordType(
                        stream: stream,
                        finalPos: finalPos,
                        offset: offset,
                        type: type,
                        lastParsed: lastParsed,
                        recordParseCount: recordParseCount,
                        translationParams: translationParams.WithNoConverter());
            }
        }
