        {
            if (obj is IFormLinkGetter formLink)
            {
                return formLink.Equals(this);
            }
            if (obj is not IKeyGetter rhs) return false;
            return ((KeyCommon)((IKeyGetter)this).CommonInstance()!).Equals(this, rhs, equalsMask: null);
        }

